function countBusyMembers() {
  let sheet = SpreadsheetApp.getActiveSheet()
  let range = sheet.getDataRange()
  let data = range.getValues()
  let busyCount = 0
  for (let i = 1; i < data.length; i++) {
    let hours = data[i][4]
    if (hours >= 10) {
      busyCount++
    }
  }
  console.log(busyCount)
}
